useCancelMessage = () => {
  const {
    abortControllers,
    setStreamingChatIds,
    setAbortControllers,
    setDownloadProgress,
  } = useStreamingContext();

  return (chatId: string) => {
    const controller = abortControllers.get(chatId);
    if (controller) {
      controller.abort();
      setStreamingChatIds(
        (prev) => new Set([...prev].filter((id) => id !== chatId)),
      );
      setAbortControllers((prev) => {
        const newMap = new Map(prev);
        newMap.delete(chatId);
        return newMap;
      });
      setDownloadProgress((prev) => {
        const newMap = new Map(prev);
        newMap.delete(chatId);
        return newMap;
      });
    }
  };
}

