void deplete_run_loop_event_queue() {
  bool done{};
  dispatch([&] { done = true; });
  while (!done) {
    MSG msg;
    if (GetMessageW(&msg, nullptr, 0, 0) > 0) {
      TranslateMessage(&msg);
      DispatchMessageW(&msg);
    }
  }
}

