llama.llama.cpp.src.llama-kv-cells.cp.source_code:
llama_kv_cells cp(const std::vector<uint32_t> & idxs) const {
    llama_kv_cells res;

    res.resize(idxs.size());

    for (uint32_t j = 0; j < idxs.size(); ++j) {
        const auto idx = idxs[j];

        res.pos[j] = pos[idx];
        res.ext[j] = ext[idx];
        res.seq[j] = seq[idx];

        assert(shift[idx] == 0);
    }

    return res;
}

llama.llama.cpp.src.llama-kv-cells.set.source_code:
void set(const std::vector<uint32_t> & idxs, const llama_kv_cells & other) {
    assert(idxs.size() == other.pos.size());

    for (uint32_t j = 0; j < other.pos.size(); ++j) {
        const auto idx = idxs[j];

        if (pos[idx] == -1 && other.pos[j] != -1) {
            used.insert(idx);
        }

        if (pos[idx] != -1 && other.pos[j] == -1) {
            used.erase(idx);
        }

        if (pos[idx] != -1) {
            seq_pos_rm(idx);
        }

        pos[idx] = other.pos[j];
        ext[idx] = other.ext[j];
        seq[idx] = other.seq[j];

        if (pos[idx] != -1) {
            seq_pos_add(idx);
        }

        assert(shift[idx] == 0);
    }
}

llama.llama.cpp.src.llama-kv-cells.rm.source_code:
void rm(uint32_t i) {
    assert(i < pos.size());
    assert(pos[i] != -1);

    seq_pos_rm(i);
    seq[i].reset();

    pos[i] = -1;
    ext[i].reset();
    shift[i] = 0;

    used.erase(i);
}

llama.llama.cpp.src.llama-kv-cells.seq_r.source_code:
bool seq_rm(uint32_t i, llama_seq_id seq_id) {
    assert(i < pos.size());
    assert(seq[i].test(seq_id));
    assert(pos[i] != -1);
    assert(seq_id >= 0);

    seq[i].reset(seq_id);
    seq_pos_dec(seq_id, pos[i]);

    if (seq[i].none()) {
        pos[i] = -1;
        ext[i].reset();
        shift[i] = 0;

        used.erase(i);

        return true;
    }

    return false;
}

llama.llama.cpp.src.llama-kv-cells.seq_k.source_code:
bool seq_keep(uint32_t i, llama_seq_id seq_id) {
    assert(i < pos.size());

    if (seq[i].test(seq_id)) {
        seq_pos_rm(i);
        seq[i].reset();

        seq[i].set(seq_id);
        seq_pos_inc(seq_id, pos[i]);

        return false;
    }

    if (seq[i].any()) {
        seq_pos_rm(i);
        seq[i].reset();

        pos[i] = -1;
        ext[i].reset();
        shift[i] = 0;

        used.erase(i);

        return true;
    }

    assert(pos[i] == -1);

    return false;
}

