    std::vector<vk_staging_memcpy> out_memcpys;
    std::vector<vk_staging_memset> memsets;

    vk_command_pool * p {};
};

struct ggml_vk_garbage_collector {
    std::vector<vk_semaphore> tl_semaphores;
